'use strict';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data=[],filter='すべて',duration='all',activeArticle=null,raf=0,expType='pendulum';
let state={saved:[],visits:{},reencounters:{}};
try{const s=JSON.parse(localStorage.getItem('curiosity-lab-v1'));if(s&&Array.isArray(s.saved)&&s.visits&&s.reencounters)state=s}catch{}
function persist(){try{localStorage.setItem('curiosity-lab-v1',JSON.stringify(state));return true}catch{toast('保存容量が不足しています。データを書き出してください。');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function save(id){const prev=[...state.saved];state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];if(!persist()){state.saved=prev;return}updateCount();$$(`[data-save="${id}"]`).forEach(b=>{b.classList.toggle('saved',state.saved.includes(id));b.textContent=state.saved.includes(id)?'✓':'+';b.setAttribute('aria-label',state.saved.includes(id)?'保存を解除':'発見を保存')});toast(state.saved.includes(id)?'コレクションに保存しました':'保存を解除しました');if(location.hash==='#collection')render()}
function updateCount(){$('#save-count').textContent=state.saved.length}
const cats=['すべて','宇宙','自然','科学','歴史','文化','心理','技術','日常'];
function chips(){return `<div class="explore-bar">${cats.map(c=>`<button class="chip ${filter===c?'active':''}" data-filter="${c}" aria-pressed="${filter===c}">${c}</button>`).join('')}<button class="random" data-random><span>⤨</span>偶然にまかせる</button></div>`}
function card(a){return `<article class="exhibit" tabindex="0" role="button" data-article="${a.id}" aria-label="${esc(a.title)}"><div class="exhibit-media"><img src="./assets/${a.image}.jpg" alt="${esc(a.subtitle)}のイメージ写真" loading="lazy"><span class="image-number">FIELD NOTE / ${String(a.number).padStart(2,'0')}</span><button class="bookmark ${state.saved.includes(a.id)?'saved':''}" data-save="${a.id}" aria-label="${state.saved.includes(a.id)?'保存を解除':'発見を保存'}">${state.saved.includes(a.id)?'✓':'+'}</button></div><div class="meta"><span class="category">${a.category} / ${({宇宙:'COSMOS',自然:'NATURE',科学:'SCIENCE',歴史:'HISTORY',文化:'CULTURE',心理:'MIND',技術:'TECHNOLOGY',日常:'EVERYDAY'})[a.category]}</span><span>${a.minutes} MIN</span></div><h3>${esc(a.title)}</h3><p>${esc(a.subtitle)}</p><div class="bottom"><span>${state.visits[a.id]?'出会った知識':'まだ知らない世界へ'}</span><span>↗</span></div></article>`}
function filtered(items){return items.filter(a=>(filter==='すべて'||a.category===filter)&&(duration==='all'||(duration==='10'?a.minutes<=10:a.minutes<=Number(duration))))}
function dueArticle(){return data.filter(a=>{let v=state.visits[a.id];return v&&Date.now()-v.first>=3*86400000&&Date.now()-(state.reencounters[a.id]||0)>=7*86400000}).sort((a,b)=>(state.reencounters[a.id]||0)-(state.reencounters[b.id]||0))[0]}
function heading(en,title,desc,controls=''){return `<div class="section-heading"><div><div class="eyebrow">${en}</div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${controls}</div>`}
function discover(){const due=dueArticle();return `<div class="page"><div class="intro"><div><div class="eyebrow">FOLLOW YOUR CURIOSITY</div><h1>世界は、まだ面白い。</h1><p>知るたびに、いつもの景色が少し変わる。</p></div><div class="date-mark">YOUR POCKET MUSEUM<br>Vol. 001 / OPEN 24 HOURS</div></div><section class="hero" role="button" tabindex="0" data-article="stardust" aria-label="私たちは星のかけらでできているを読む"><img src="./assets/space.jpg" alt="無数の星がきらめく星雲"><div class="hero-index">01 <span>/ THE UNIVERSE & US</span></div><div class="hero-copy"><div class="exhibit-label">今夜、ひとつの不思議を。</div><h2>私たちは、星のかけらで<br>できている。</h2><p>あなたの体にある炭素も、呼吸する酸素も。<br>はるか昔、星の中で生まれたものかもしれない。</p><span class="pill">この世界をのぞく <span>↗</span></span></div><div class="hero-foot">COSMOS　·　5 MIN READ</div></section>${chips()}${due?`<section class="resurface" data-revisit="${due.id}" tabindex="0" role="button"><div class="eyebrow">HELLO, AGAIN</div><h3>もう一度、違う角度から。</h3><p>${esc(due.revisit)}</p><span class="text-link">${esc(due.title)} ↗</span></section>`:''}${heading('CABINET OF WONDERS','今日は、どこへ寄り道する？','小さな発見から、思いがけない世界へ。',`<select id="duration" aria-label="読む時間"><option value="all">時間を気にせず</option value="3">3分の寄り道</option value="5">5分でひと巡り</option value="10">10分以内</option></select>`)}<div class="exhibits" id="exhibits">${filtered(data.filter(x=>filter!=='すべて'||x.id!=='stardust')).map(card).join('')||'<p class="empty">この条件の展示は準備中です。別の分野も巡ってみませんか。</p>'}</div><section class="lab-teaser"><div class="copy"><div class="eyebrow">THE INTERACTIVE LAB</div><h2>読むだけじゃ、<br>わからないこともある。</h2><p>動かして、比べて、「なるほど」に出会う。</p><a class="text-link" href="#lab">実験室の扉を開く　↗</a></div><div class="wave-art"><div class="orb"></div></div></section>${heading('WATCH & WONDER','映像で、腑に落ちる。','図解とアニメーションで、知識の入口へ。',`<a href="#videos" class="text-link">動画の展示室 ↗</a>`)}<div class="video-grid">${videos.slice(0,2).map(videoCard).join('')}</div></div>`}
const videos=[{id:'l8_fZPHasdo',title:'私たちは、どうやって色を見る？',original:'How we see color — Colm Kelleher',level:'はじめの一本',url:'https://ed.ted.com/lessons/how-we-see-color-colm-kelleher',note:'錐体と色の知覚をアニメーションで説明。英語音声。日本語字幕の有無はプレーヤーで確認できます。'}, {id:'UZ5UGnU7oOI',title:'そもそも「色」って、なんだろう。',original:'What is color? — Colm Kelleher',level:'さらに深く',url:'https://ed.ted.com/lessons/how-do-we-see-color-colm-kelleher',note:'光の波と周波数を扱う、色の物理への入口。英語音声。日本語字幕の有無はプレーヤーで確認できます。'}];
function videoCard(v){return `<article class="video"><div class="video-preview" id="video-${v.id}"><img loading="lazy" src="https://i.ytimg.com/vi/${v.id}/hqdefault.jpg" alt="${esc(v.original)}の動画サムネイル"><button class="play" data-video="${v.id}" aria-label="${esc(v.title)}を再生">▶</button></div><div class="meta"><span>TED-Ed</span><span>${v.level}</span></div><h3>${v.title}</h3><p>${v.note}</p><details class="evaluation"><summary>わかりやすさの評価：採点保留 · 信頼度は限定的</summary><p>公式教材ページで作者・制作元・説明形式を確認。映像全体と字幕を通して評価していないため、合計点や順位は付けていません。</p><dl><dt>図・実験・実物</dt><dd>未評価 / 30</dd><dt>初心者向けの構成</dt><dd>未評価 / 25</dd><dt>説明と映像の一致</dt><dd>未評価 / 20</dd><dt>正確性・出典</dt><dd>未評価 / 15</dd><dt>テンポ・見やすさ</dt><dd>未評価 / 10</dd></dl><a class="text-link" href="${v.url}" target="_blank" rel="noopener">公式教材ページ ↗</a></details><p class="fine">再生するとYouTubeに接続します。再生不可の場合は <a href="https://www.youtube.com/watch?v=${v.id}" target="_blank" rel="noopener">YouTubeで開く ↗</a></p></article>`}
function collection(){const items=filtered(data.filter(a=>state.saved.includes(a.id)));return `<div class="page"><div class="eyebrow">YOUR CABINET OF CURIOSITIES</div><h1 class="route-title">心が動いた、世界のかけら。</h1><p class="route-intro">覚えるためではなく、また会いたくなるから。<br>あなたが集めた発見のコレクション。</p>${chips()}${heading('COLLECTED WONDERS',`${state.saved.length} 個の発見`,'並び順：最近保存したものから',`<button class="text-link" id="export">データを書き出す ↗</button>`)}<div class="exhibits">${items.sort((a,b)=>state.saved.indexOf(b.id)-state.saved.indexOf(a.id)).map(card).join('')}</div>${!items.length?'<div class="empty"><h2>心に残る発見を、ここに。</h2><p>展示の「＋」を押すと保存できます。<br>他の端末へ移すときは、データを書き出してください。</p><a class="text-link" href="#discover">探検に出かける ↗</a></div>':''}</div>`}
function atlas(){const viewed=Object.keys(state.visits).length;const positions=[[390,105],[160,205],[620,350],[405,275],[610,160],[215,395],[650,65],[440,430],[70,325],[85,90],[285,70],[540,315]];return `<div class="page"><div class="eyebrow">THE CONSTELLATION OF KNOWLEDGE</div><h1 class="route-title">発見は、星座になる。</h1><p class="route-intro">色から心理へ。月から海へ。<br>分野の境界を越えて、ひとつの疑問が次の世界を照らします。</p><div class="atlas-shell"><svg viewBox="0 0 750 510" role="group" aria-label="知識の関連を巡る星図。各星を選ぶと展示が開きます。">${data.map((a,i)=>a.related.map(id=>{const j=data.findIndex(x=>x.id===id);if(j<0||j<i)return '';return `<line x1="${(positions[i]||[350+Math.cos(i*2.4)*270,255+Math.sin(i*2.4)*200])[0]}" y1="${(positions[i]||[350+Math.cos(i*2.4)*270,255+Math.sin(i*2.4)*200])[1]}" x2="${(positions[j]||[350+Math.cos(j*2.4)*270,255+Math.sin(j*2.4)*200])[0]}" y2="${(positions[j]||[350+Math.cos(j*2.4)*270,255+Math.sin(j*2.4)*200])[1]}" stroke="#8eaf8c" stroke-opacity=".25" stroke-width="1"/>`}).join('')).join('')}${data.map((a,i)=>{const [x,y]=positions[i]||[350+Math.cos(i*2.4)*270,255+Math.sin(i*2.4)*200],known=!!state.visits[a.id];return `<g class="node" role="button" tabindex="0" aria-label="${esc(a.title)} ${known?'発見済み':'未探索'}" data-article="${a.id}" transform="translate(${x},${y})"><circle r="${known?13:8}" fill="${known?'#dbdca0':'#638d7d'}" stroke="#e3eacc" stroke-opacity="${known?.8:.3}" stroke-width="${known?5:1}"/><text x="0" y="32" text-anchor="middle">${esc(a.subtitle.split('、')[0].slice(0,14))}</text><text x="0" y="49" text-anchor="middle" style="font-size:9px;fill:#a7bfae">${a.category}</text></g>`}).join('')}</svg><div class="atlas-legend">● 発見した星 ${viewed}　·　● まだ知らない世界 ${data.length-viewed}<br><br>星をタップして探索 · スマートフォンでは横に動かせます</div></div><div class="tools-row"><button data-random>⤨ 知らない星に寄り道する</button><button id="atlas-known">出会った知識をたどる</button></div>${heading('UNEXPECTED CONNECTIONS','思いがけない、つながり。','アプリが用意した関連テーマ。未読の星も探検できます。')}<div class="exhibits">${data.filter(a=>['color','blue','sky'].includes(a.id)).map(card).join('')}</div></div>`}
function lab(){return `<div class="page"><div class="eyebrow">THE INTERACTIVE LAB</div><h1 class="route-title">触れると、世界が動きだす。</h1><p class="route-intro">答えを当てなくていい。変えて、眺めて、気になったらもう一度。</p><div class="experiment-tabs"><button data-exp="pendulum" class="${expType==='pendulum'?'active':''}">01 振り子のリズム</button><button data-exp="illusion" class="${expType==='illusion'?'active':''}">02 同じ灰色、違う灰色</button><button data-exp="chance" class="${expType==='chance'?'active':''}">03 偶然を眺める</button></div><section id="experiment" class="experiment"></section></div>`}
function setupExperiment(){cancelAnimationFrame(raf);let el=$('#experiment');if(!el)return;
if(expType==='pendulum'){el.innerHTML=`<div class="eyebrow">PHYSICS / SMALL-ANGLE MODEL</div><h2>長くすると、どれだけゆっくり？</h2><p>ひもの長さを変えてみてください。比較用の薄い振り子は、長さ1 m。小さな振れ幅・摩擦なしの理想モデルです。</p><canvas id="pendulum" aria-label="長さを変えると周期が変わる振り子の図"></canvas><div class="control"><label for="length">ひもの長さ</label><input id="length" type="range" min="0.25" max="2" step="0.05" value="1"><output id="length-out">1.00 m</output></div><div class="tools-row"><button id="pause">一時停止</button><button id="restart">はじめから</button></div><div>一往復の時間 <span class="stat" id="period">2.01</span> 秒</div><p>T = 2π√(L/g)、g = 9.81 m/s²。長さを4倍にすると周期は2倍になります。モデルの動きは実際の秒数に合わせています。</p><button class="text-link" data-article="wave">振り子の展示へ ↗</button>`;
let c=$('#pendulum'),ctx=c.getContext('2d'),time=0,last=0,paused=false;$('#pause').onclick=()=>{paused=!paused;$('#pause').textContent=paused?'再開する':'一時停止'};$('#restart').onclick=()=>{time=0};const frame=now=>{if(!c.isConnected)return;let rect=c.getBoundingClientRect(),dpr=devicePixelRatio||1;if(c.width!==Math.round(rect.width*dpr)||c.height!==Math.round(rect.height*dpr)){c.width=Math.round(rect.width*dpr);c.height=Math.round(rect.height*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);let w=rect.width,h=rect.height,L=Number($('#length').value),T=2*Math.PI*Math.sqrt(L/9.81);if(last&&!paused)time+=Math.min((now-last)/1000,.1);last=now;$('#length-out').textContent=L.toFixed(2)+' m';$('#period').textContent=T.toFixed(2);ctx.clearRect(0,0,w,h);[[1,'#b6c2af',w*.35],[L,'#385e45',w*.65]].forEach(([l,col,x])=>{let len=65+l*60,theta=.20*Math.cos(Math.sqrt(9.81/l)*time),y=25,bx=x+Math.sin(theta)*len,by=y+Math.cos(theta)*len;ctx.strokeStyle=col;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(bx,by);ctx.stroke();ctx.fillStyle=col;ctx.beginPath();ctx.arc(bx,by,12,0,Math.PI*2);ctx.fill();ctx.font='11px sans-serif';ctx.textAlign='center';ctx.fillText(l.toFixed(2)+' m',x,h-18)});raf=requestAnimationFrame(frame)};raf=requestAnimationFrame(frame)
}else if(expType==='illusion'){el.innerHTML=`<div class="eyebrow">PERCEPTION / SIMULTANEOUS CONTRAST</div><h2>このふたつ、同じ明るさです。</h2><p>左右の四角は、どちらも同じ灰色（#888888）。背景との関係で、違う明るさに見えることがあります。</p><div class="illusion" id="illusion"><span></span><span></span></div><div class="tools-row"><button class="primary" id="reveal">背景を外してみる</button></div><p>目の順応や周囲との比較が、明るさの知覚に関わります。画面や視覚の個人差によって感じ方は異なります。</p><button class="text-link" data-article="color">色の見え方の展示へ ↗</button><div class="source-list"><a href="https://www.exploratorium.edu/snacks/gray-step" target="_blank" rel="noopener">仕組みの出典：Exploratorium — Gray Step ↗</a></div>`;$('#reveal').onclick=()=>{const on=$('#illusion').classList.toggle('reveal');$('#reveal').textContent=on?'背景を戻す':'背景を外してみる'}
}else{el.innerHTML=`<div class="eyebrow">PROBABILITY / INDEPENDENT TRIALS</div><h2>偶然は、少しでこぼこしている。</h2><p>表の確率が50%のコインをシミュレーションします。少ない回数では偏り、大きな回数では比率がどう変化するか眺めてみましょう。</p><canvas id="chance-chart" aria-label="試行回数に対する表の割合。中央の線は50パーセント"></canvas><div class="tools-row"><button class="primary" data-flip="10">10回投げる</button><button class="secondary" data-flip="100">100回投げる</button><button class="secondary" id="reset-coins">リセット</button></div><p id="chance-status" aria-live="polite">まだ投げていません。</p><p>点線は50%。前の結果は次の確率を変えません。これは擬似乱数による教材で、賭け事の予測には使えません。</p><button class="text-link" data-article="chance">偶然の展示へ ↗</button>`;let n=0,heads=0,points=[],c=$('#chance-chart'),ctx=c.getContext('2d');function draw(){const r=c.getBoundingClientRect(),d=devicePixelRatio||1;c.width=r.width*d;c.height=r.height*d;ctx.scale(d,d);const w=r.width,h=r.height;ctx.clearRect(0,0,w,h);ctx.setLineDash([5,5]);ctx.strokeStyle='#a8b99c';ctx.beginPath();ctx.moveTo(30,h/2);ctx.lineTo(w-10,h/2);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle='#3c6549';ctx.lineWidth=1.5;ctx.beginPath();points.forEach((p,i)=>{const x=30+i/Math.max(1,points.length-1)*(w-45),y=15+(1-p)*(h-35);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.fillStyle='#65755b';ctx.font='10px sans-serif';ctx.fillText('100%',0,18);ctx.fillText('50%',0,h/2);ctx.fillText('0%',5,h-20)}$$('[data-flip]',el).forEach(b=>b.onclick=()=>{if(n>=10000){toast('1万回を観察しました。リセットして新しい偶然へ。');return}for(let i=0;i<Number(b.dataset.flip);i++){n++;if(Math.random()<.5)heads++;points.push(heads/n)}$('#chance-status').textContent=`${n}回投げました。表 ${heads}回 / 裏 ${n-heads}回。表の割合 ${(100*heads/n).toFixed(1)}%。`;draw()});$('#reset-coins').onclick=()=>{n=0;heads=0;points=[];$('#chance-status').textContent='まだ投げていません。';draw()};draw()}}
function render(){cancelAnimationFrame(raf);const route=location.hash.slice(1)||'discover';$$('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));$('#app').innerHTML=route==='atlas'?atlas():route==='collection'?collection():route==='lab'?lab():route==='videos'?`<div class="page"><div class="eyebrow">WATCH & WONDER</div><h1 class="route-title">映像で、腑に落ちる。</h1><p class="route-intro">人気の数字より、理解のきっかけを。<br>公式教材から選んだ2本。採点は実視聴での確認後に行います。</p><div class="video-grid">${videos.map(videoCard).join('')}</div></div>`:discover();if($('#duration'))$('#duration').value=duration;if(route==='lab')setupExperiment();updateCount()}
function read(id){let a=data.find(x=>x.id===id);if(!a)return;activeArticle=a;let v=state.visits[id];state.visits[id]={first:v?.first||Date.now(),last:Date.now(),count:(v?.count||0)+1};persist();$('#reader-body').innerHTML=`<div class="reader-hero"><img src="./assets/${a.image}.jpg" alt="${esc(a.subtitle)}のイメージ写真"></div><div class="reader-content"><div class="eyebrow">${a.category} / FIELD NOTE ${String(a.number).padStart(2,'0')}</div><h1>${esc(a.title)}</h1><p class="lead">${esc(a.summary)}</p><div class="tools-row"><button aria-label="発見を保存・解除" data-save="${id}" class="secondary ${state.saved.includes(id)?'saved':''}">${state.saved.includes(id)?'✓':'+'}</button><button id="reader-talk-link">一言で話す ↘</button><button id="reader-gpt-link">GPTと深掘り ↘</button></div><div class="read-modes" aria-label="読み方"><button class="active" data-mode="short">3分 / 要点</button><button data-mode="full">5分 / 背景まで</button><button data-mode="deep">じっくり / 出典へ</button></div><div class="fact"><strong>ひとつ、持ち帰るなら。</strong><p>${esc(a.sections[0].text)}</p></div><div class="more-section" hidden>${a.sections.map(s=>`<h2>${esc(s.heading)}</h2><p>${esc(s.text)}</p>`).join('')}<p class="fine">本文は入門向けの要約です。条件や例外を含む詳細は、下の出典で確認できます。</p></div>${['wave','color','chance'].includes(id)?`<a class="text-link" href="#lab" id="article-lab">手を動かして確かめる ↗</a>`:''}<section class="talk" id="talk"><div class="eyebrow">A LITTLE SOMETHING TO SHARE</div><p>${esc(a.talk)}</p><button class="text-link" id="copy-talk">30秒の雑談をコピーする　↗</button></section><section class="bridge" id="bridge"><div class="eyebrow">CONTINUE WITH CHATGPT</div><h3>この「なぜ？」の、その先へ。</h3><label for="bridge-mode">どんなふうに話してみる？</label><select id="bridge-mode"><option>知識を深掘りする</option><option>雑談ネタとして発展させる</option><option>創作のアイデアとして検討する</option><option>目的を決めずに共有する</option></select><label for="bridge-part" class="fine">引き継ぐ一部分・質問（空欄なら記事全体）</label><textarea id="bridge-part" placeholder="気になる段落を選択して下のボタンで取り込む、または質問を書く"></textarea><button class="text-link" id="use-selection">選択した文章を取り込む</button><div><button class="primary" id="copy-bridge">引き継ぎ文をコピー</button><a class="secondary" href="https://chatgpt.com/" target="_blank" rel="noopener">ChatGPTを開く ↗</a></div><p class="fine">コピーしてChatGPTに貼り付けると、出典と前提をまとめて渡せます。アプリ内対話・API課金はありません。</p></section><section class="source-list" id="sources"><h2>確かめる、もっと知る。</h2>${a.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.name)} ↗</a>`).join('')}<small>出典確認日：${a.checked}${a.review?'（生成記事・自動出典照合）':''} · 写真はテーマのイメージです（Unsplash）。</small></section><h2>次の寄り道。</h2><div>${a.related.map(id=>{const r=data.find(x=>x.id===id);return r?`<button class="search-result" data-article="${id}"><small>${r.category}</small>${esc(r.title)}　↗</button>`:''}).join('')}</div></div>`;if(!$('#reader').open)$('#reader').showModal();$('#reader').scrollTop=0;$('#copy-talk').onclick=()=>copy(a.talk);$('#reader-talk-link').onclick=()=>$('#talk').scrollIntoView({behavior:'smooth'});$('#reader-gpt-link').onclick=()=>$('#bridge').scrollIntoView({behavior:'smooth'});$('#copy-bridge').onclick=()=>copy(bridgeText(a));$('#use-selection').onclick=()=>{const selection=window.getSelection()?.toString().trim();if(selection){$('#bridge-part').value=selection;toast('選択した文章を取り込みました')}else toast('記事中の気になる文章を長押しして選択してください')};if($('#article-lab'))$('#article-lab').onclick=()=>{$('#reader').close();expType=id==='wave'?'pendulum':id==='color'?'illusion':'chance';if(location.hash==='#lab')render()};$$('[data-mode]',$('#reader')).forEach(b=>b.onclick=()=>{$$('[data-mode]',$('#reader')).forEach(x=>x.classList.toggle('active',x===b));$('.more-section',$('#reader')).hidden=b.dataset.mode==='short';if(b.dataset.mode==='deep')$('#sources').scrollIntoView({behavior:'smooth'})})}
function bridgeText(a){return `【Curiosity Labからの引き継ぎ】\nテーマ：${a.title}\n依頼モード：${$('#bridge-mode').value}\n概要：${a.summary}\n重要な事実：\n${a.sections.map(s=>s.heading+'：'+s.text).join('\n')}\n出典（確認日 ${a.checked}）：\n${a.sources.map(s=>s.name+' '+s.url).join('\n')}\n関連情報：${a.related.map(id=>data.find(x=>x.id===id)?.title||'').filter(Boolean).join(' / ')}\n選択部分・質問：${$('#bridge-part').value||'記事全体を共有します。'}\n依頼：上記のモードで対話を始めてください。出典の事実、推測、創作案を区別してください。創作への転用は私が判断します。前提を繰り返し質問せず、まず内容に即した提案をしてください。`}
async function copy(t){try{await navigator.clipboard.writeText(t);toast('コピーしました。気になる相手へ、世界のかけらを。')}catch{const ta=document.createElement('textarea');ta.value=t;document.body.append(ta);ta.select();const ok=document.execCommand('copy');ta.remove();if(ok)toast('コピーしました');else{const d=document.createElement('dialog');d.innerHTML='<div style="padding:30px"><h2>文章を長押ししてコピー</h2><textarea style="width:100%;height:50vh"></textarea><form method="dialog"><button class="primary">閉じる</button></form></div>';d.querySelector('textarea').value=t;document.body.append(d);d.showModal();d.onclose=()=>d.remove()}}}
function exportData(){const blob=new Blob([JSON.stringify({app:'CuriosityLab',version:1,...state},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='curiosity-lab-discoveries.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('発見のデータを書き出しました')}
function settings(){const d=document.createElement('dialog');d.innerHTML=`<div class="reader-content"><form method="dialog"><button class="secondary">閉じる ×</button></form><h1>あなたの発見を、大切に。</h1><p>保存と閲覧履歴は、この端末・このブラウザーに保存されます。アカウントへの同期はありません。ホーム画面版とSafariの保存領域が異なる場合は、書き出しと読み込みで移せます。</p><div class="tools-row"><button id="data-export" class="primary">書き出す</button><label class="secondary" for="import-data">データを読み込む</label><input type="file" id="import-data" accept="application/json" hidden></div><h2>ホーム画面から、博物館へ。</h2><p>iPhoneのSafariで開き、共有 →「ホーム画面に追加」を選んでください。一度開いた展示や実験はオフラインでも利用できます。動画、外部出典、ChatGPTには通信が必要です。</p><h2>もう一度出会う</h2><p>初めて触れてから3日以上たった知識を、トップに別の切り口で再表示します。同じ展示の再表示は7日以上空けます。通知やテストはありません。</p><h2>コンテンツと更新</h2><p>初期展示は13テーマ。記事に一次出典を表示しています。GitHub Actionsで毎週月・水・金の朝7時（日本時間）に、事前確認済みの記事を1件ずつ追加する設定です。配信待ちは5件。候補が尽きた場合や更新に失敗した場合も、既存の展示を残します。定期実行の初回結果はまだ確認前です。</p><p>動画の100点評価は実視聴による検証待ちです。未確認の点数は付けていません。写真は説明対象そのものを保証するものではなく、テーマのイメージです。</p><h2>写真について</h2><p>画像提供：Unsplash。星雲、クラゲ、森、地球、海、都市、エジプトの写真を使用しています。写真の配信元URLと利用条件はソース内のASSETS.mdに記載しています。</p><p class="fine">Curiosity Lab v1.0 · 世界を知ることを、娯楽に。</p></div>`;document.body.append(d);d.showModal();d.onclose=()=>d.remove();$('#data-export',d).onclick=exportData;$('#import-data',d).onchange=async e=>{try{const file=e.target.files[0];if(file.size>2e6)throw Error();const s=JSON.parse(await file.text());if(s.app!=='CuriosityLab'||!Array.isArray(s.saved)||!s.visits||!s.reencounters)throw Error();let visits={...state.visits};for(const [id,v]of Object.entries(s.visits)){if(data.some(a=>a.id===id)&&v&&Number.isFinite(v.first)&&Number.isFinite(v.last)&&Number.isFinite(v.count))visits[id]=v}state={saved:[...new Set([...state.saved,...s.saved.filter(id=>data.some(a=>a.id===id))])],visits,reencounters:{...state.reencounters,...Object.fromEntries(Object.entries(s.reencounters).filter(([id,v])=>data.some(a=>a.id===id)&&Number.isFinite(v)))}};persist();render();toast('発見を読み込みました');d.close()}catch{toast('Curiosity Labの書き出しファイルを選んでください')}}}
document.addEventListener('click',e=>{const s=e.target.closest('[data-save]');if(s){e.stopPropagation();save(s.dataset.save);return}const a=e.target.closest('[data-article]');if(a){read(a.dataset.article);return}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;render();return}if(e.target.closest('[data-random]')){const unvisited=data.filter(a=>!state.visits[a.id]),pool=unvisited.length?unvisited:data;read(pool[Math.floor(Math.random()*pool.length)].id);return}const v=e.target.closest('[data-video]');if(v){$('#video-'+v.dataset.video).innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${v.dataset.video}?autoplay=1&cc_load_policy=1&cc_lang_pref=ja" title="TED-Ed 動画" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`;return}const x=e.target.closest('[data-exp]');if(x){expType=x.dataset.exp;render();return}const re=e.target.closest('[data-revisit]');if(re){state.reencounters[re.dataset.revisit]=Date.now();persist();read(re.dataset.revisit)}if(e.target.closest('#export'))exportData();if(e.target.closest('#atlas-known')){const found=data.filter(a=>state.visits[a.id]);found.length?read(found[Math.floor(Math.random()*found.length)].id):toast('まだ白紙の星図です。気になる星を選んでみましょう。')}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"]')){e.preventDefault();e.target.click()}});document.addEventListener('change',e=>{if(e.target.id==='duration'){duration=e.target.value;render()}});$('.close-reader').onclick=()=>$('#reader').close();$('#reader').addEventListener('close',()=>{activeArticle=null;if(['#atlas','#collection'].includes(location.hash))render()});$('#settings').onclick=settings;$('#search-open').onclick=()=>{$('#search-dialog').showModal();$('#search-input').focus();search()};function search(){let q=$('#search-input').value.trim().toLowerCase(),matches=data.filter(a=>[a.title,a.summary,a.category,a.subtitle].join(' ').toLowerCase().includes(q));$('#search-results').innerHTML=matches.length?matches.map(a=>`<button class="search-result" data-article="${a.id}"><small>${a.category} · ${a.minutes} MIN</small>${esc(a.title)} ↗</button>`).join(''):'<p>まだ展示されていないテーマです。別の言葉でも探してみてください。</p>'}$('#search-results').onclick=e=>{if(e.target.closest('[data-article]'))$('#search-dialog').close()};$('#search-input').oninput=search;window.addEventListener('hashchange',()=>{if($('#reader').open)$('#reader').close();render();window.scrollTo(0,0)});
async function boot(){try{const res=await fetch('./content.json',{cache:'no-cache'});if(!res.ok)throw Error();const content=await res.json();data=content.articles;if(!Array.isArray(data)||!data.length)throw Error();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}catch{$('#app').innerHTML='<div class="page empty"><h1>展示の準備に接続できませんでした。</h1><p>初めての起動には通信が必要です。</p><button class="primary" onclick="location.reload()">もう一度開く</button></div>'}}boot();
